/**
 * Versi ringkas `newsItems` tanpa field `content`.
 *
 * Isi lengkap artikel (~59 KB HTML) hanya dibutuhkan halaman detail
 * `/berita/[slug]`. Bila array mentahnya diteruskan ke Client Component,
 * seluruh isi artikel ikut terserialisasi ke payload RSC dan ikut terbundel
 * ke JavaScript sisi klien. Proyeksi ini mencegah hal tersebut.
 */
export type NewsSummary = Omit<(typeof newsItems)[number], "content">;

export function toNewsSummaries(items: typeof newsItems): NewsSummary[] {
  return items.map(({ content, ...rest }) => rest);
}

